export const DEFAULT_REFUSAL = 'This request cannot be processed because it conflicts with the usage policy of this assistant.';
export const DEFAULT_LABEL = 'Generated by AI. Review before use.';
/** Built-in patterns for Qatar identifiers; used for log masking when a policy carries no patterns of its own. */
export const BUILT_IN_PATTERNS = [
    { name: 'QID', regex: '\\b[23]\\d{10}\\b', replace: '[QID masked]' },
    { name: 'IBAN', regex: '\\bQA\\d{2}[A-Z]{4}[A-Z0-9]{21}\\b', replace: '[IBAN masked]' },
    { name: 'Phone', regex: '\\+974[ -]?\\d{4}[ -]?\\d{4}\\b', replace: '[Phone masked]' },
    { name: 'Email', regex: '\\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}\\b', replace: '[Email masked]' },
];
export class PolicyError extends Error {
}
const isDict = (v) => typeof v === 'object' && v !== null && !Array.isArray(v);
const dict = (v) => (isDict(v) ? v : {});
const strings = (v) => (Array.isArray(v) ? v.filter((x) => typeof x === 'string') : []);
const days = (v) => (typeof v === 'number' && Number.isFinite(v) && v >= 0 ? v : null);
/**
 * Validates a policy document and fills every absent section with its "off" value, so the rest of the gate
 * never has to test for a missing section. Throws PolicyError on anything that cannot be enforced safely.
 */
export function normalisePolicy(raw, assetId) {
    if (!isDict(raw))
        throw new PolicyError('policy must be an object');
    if (typeof raw.version !== 'number' || !Number.isInteger(raw.version) || raw.version < 0) {
        throw new PolicyError('policy.version must be a non-negative integer');
    }
    if (raw.assetId !== undefined && raw.assetId !== assetId)
        throw new PolicyError(`policy.assetId is not ${assetId}`);
    const masking = dict(raw.masking);
    const patterns = (Array.isArray(masking.patterns) ? masking.patterns : []).map((p, i) => {
        const d = dict(p);
        if (typeof d.regex !== 'string' || typeof d.replace !== 'string')
            throw new PolicyError(`masking.patterns[${i}] needs regex and replace`);
        try {
            new RegExp(d.regex, 'g');
        }
        catch {
            throw new PolicyError(`masking.patterns[${i}].regex does not compile`);
        }
        return { name: typeof d.name === 'string' ? d.name : `pattern-${i}`, regex: d.regex, replace: d.replace };
    });
    const input = dict(raw.input);
    const deniedTopics = (Array.isArray(input.deniedTopics) ? input.deniedTopics : []).map((t, i) => {
        const d = dict(t);
        return { name: typeof d.name === 'string' ? d.name : `topic-${i}`, phrases: strings(d.phrases) };
    });
    const aiLabel = dict(raw.aiLabel);
    const roles = dict(raw.roles);
    const map = {};
    for (const [prefix, allowed] of Object.entries(dict(roles.map)))
        map[prefix] = strings(allowed);
    const retention = dict(raw.retention);
    return {
        version: raw.version,
        issuedAt: typeof raw.issuedAt === 'string' ? raw.issuedAt : new Date(0).toISOString(),
        assetId,
        masking: { enabled: masking.enabled === true, patterns, unmaskedRoles: strings(masking.unmaskedRoles) },
        input: {
            refuseInjection: input.refuseInjection === true,
            deniedTopics,
            refusal: typeof input.refusal === 'string' && input.refusal ? input.refusal : DEFAULT_REFUSAL,
        },
        aiLabel: { enabled: aiLabel.enabled === true, text: typeof aiLabel.text === 'string' && aiLabel.text ? aiLabel.text : DEFAULT_LABEL },
        roles: { enforce: roles.enforce === true, map },
        retention: { conversationsDays: days(retention.conversationsDays), logsDays: days(retention.logsDays) },
        logging: { maskPersonalData: dict(raw.logging).maskPersonalData === true },
        telemetry: { enabled: dict(raw.telemetry).enabled === true },
    };
}
